export const apWorldHistoryFRQs: WorldHistoryFRQ[] = [...longFRQs, ...shortFRQs, ...dbqFRQs]

export function getApWorldHistoryFRQs(): WorldHistoryFRQ[] {
  return apWorldHistoryFRQs
}

export function getLongFRQs(): WorldHistoryFRQ[] {
  return longFRQs
}

export function getShortFRQs(): WorldHistoryFRQ[] {
  return shortFRQs
}

export function getDBQs(): WorldHistoryFRQ[] {
  return dbqFRQs
}

export function generateFullExamFRQs(pool: WorldHistoryFRQ[] = apWorldHistoryFRQs): {
  long: WorldHistoryFRQ[]
  short: WorldHistoryFRQ[]
  totalPoints: number
  totalTime: string
} {
  const shuffle = <T>(arr: T[]): T[] => {
    const copy = [...arr]
    for (let i = copy.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1))
      ;[copy[i], copy[j]] = [copy[j], copy[i]]
    }
    return copy
  }

  const selectedLong = shuffle(pool.filter((f) => f.type === 'long')).slice(0, 2)
  const selectedShort = shuffle(pool.filter((f) => f.type === 'short')).slice(0, 2)
  const totalPoints = [...selectedLong, ...selectedShort].reduce((s, f) => s + f.totalPoints, 0)

  return {
    long: selectedLong,
    short: selectedShort,
    totalPoints,
    totalTime: '100 min',
  }
}
